@dataclass
class Response:
    status: int
    body: str = ""
    headers: dict[str, str] = field(default_factory=dict)


class ApiService:
    def __init__(self, limiter: TokenBucketLimiter) -> None:
        self.limiter = limiter

    def handle(self, req: Request) -> Response:
        key = f"key:{req.api_key}" if req.api_key else f"ip:{req.client_ip}"
        decision = self.limiter.check(key, ROUTE_COST.get(req.path, 1.0))
        if not decision.allowed:
            return Response(429, "rate limited",
                            {"Retry-After": f"{decision.retry_after:.3f}"})
        return Response(200, f"ok {req.path}")

