@dataclass(frozen=True)
class Decision:
    allowed: bool
    retry_after: float = 0.0


class TokenBucketLimiter:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Clock) -> None:
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self._buckets: dict[str, tuple[float, float]] = {}

    def check(self, key: str, cost: float = 1.0) -> Decision:
        if cost > self.capacity:
            raise ValueError("cost exceeds bucket capacity")
        now = self.clock.now()
        tokens, last = self._buckets.get(key, (self.capacity, now))
        tokens = min(self.capacity, tokens + (now - last) * self.refill_per_sec)
        if tokens >= cost:
            self._buckets[key] = (tokens - cost, now)
            return Decision(True, 0.0)
        self._buckets[key] = (tokens, now)
        return Decision(False, (cost - tokens) / self.refill_per_sec)

