import math

import torch


def split_heads(x: torch.Tensor, n_heads: int) -> torch.Tensor:
    """[B, T, D] -> [B, H, T, D // H]"""
    b, t, d = x.shape
    return x.view(b, t, n_heads, d // n_heads).transpose(1, 2)


def merge_heads(x: torch.Tensor) -> torch.Tensor:
    """[B, H, T, Dh] -> [B, T, H * Dh]"""
    b, h, t, dh = x.shape
    return x.transpose(1, 2).reshape(b, t, h * dh)


def attend(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor) -> torch.Tensor:
    """One decode step. q: [B, H, 1, Dh]; k, v: [B, H, T, Dh] -> [B, H, 1, Dh]"""
    if q.shape[-2] != 1:
        raise ValueError("attend() handles a single decode step: q must have length 1")
    scores = q @ k.transpose(-1, -2) / math.sqrt(q.shape[-1])
    return torch.softmax(scores, dim=-1) @ v

import torch

from leegen_harness import device


def make_inputs(seed: int, B: int, T: int, D: int, H: int):
    g = torch.Generator().manual_seed(seed)
    dev = device()
    scale = D ** -0.5

    def rand(*shape, s=1.0):
        return (torch.randn(*shape, generator=g) * s).to(dev)

    return {"x": rand(B, T, D), "w_q": rand(D, D, s=scale), "w_k": rand(D, D, s=scale),
            "w_v": rand(D, D, s=scale), "n_heads": H}


def full_causal_attention(x, w_q, w_k, w_v, n_heads):
    """Independent check used while authoring: non-cached causal attention."""
    b, t, d = x.shape
    q, k, v = (m.view(b, t, n_heads, d // n_heads).transpose(1, 2)
               for m in (x @ w_q, x @ w_k, x @ w_v))
    mask = torch.ones(t, t, dtype=torch.bool, device=x.device).tril()
    scores = (q @ k.transpose(-1, -2)) / (d // n_heads) ** 0.5
    scores = scores.masked_fill(~mask, float("-inf"))
    out = torch.softmax(scores, -1) @ v
    return out.transpose(1, 2).reshape(b, t, d)
